using Microsoft.UI.Xaml;

namespace PrTracker.WinUI;

/// <summary>
/// Application entry point. The actual <c>Main</c> method is generated by the
/// Windows App SDK / WinUI tooling (XAML generated Main); we only override
/// <see cref="OnLaunched"/> to create and activate the main window.
/// </summary>
public partial class App : Application
{
    private Window? _window;

    public App()
    {
        InitializeComponent();
    }

    protected override void OnLaunched(LaunchActivatedEventArgs args)
    {
        _window = new MainWindow();
        _window.Activate();
    }
}
